     "t": "math",
     "tex": "\\boxed{a^n \\cos(\\omega_0 n) u[n] \\stackrel{\\mathcal{Z}}{\\longleftrightarrow} \\frac{z^2 - a z \\cos\\omega_0}{z^2 - 2 a z \\cos\\omega_0 + a^2}, \\quad \\text{ROC: } \\vert z \\vert > \\vert a \\vert}"
